     "title": "平台比人民还想“杀死”双十一",
     "url": "https://www.huxiu.com/article/4904857.html",
     "time": "11-11 21:30",
     "ts": 1794403817,
     "summary": "本文来自微信公众号： 星海情报局 ，作者：星海老局双十一才刚满十八岁，亲手把它养大的电商平台，就已经开始琢磨怎么干掉它了。今年10月15日，天猫和京东不约而同地在同一天召开双十一发布会。放在前些年，这几乎就是两家电商巨头一年一度最热血的战前动员，折扣、补贴、流量、成交目标……但凡喊不出空前绝后的气势就算输了。但今年，两家平台显然有了新的算盘。天猫宣布有100万个品牌、7200万款商品参加大促。但比起折扣，天猫总裁家洛更愿意谈AI如何发现消费者尚未表达的需求，如何帮品牌找到新的",
